import sys
import os
import hashlib
import time

def compute_fingerprint(file_path):
    try:
        with open(file_path, 'rb') as f:
            content = f.read()
            return hashlib.sha256(content).hexdigest()[:16].lower()
    except (IOError, OSError):
        return "error"

def main():
    rate = int(sys.argv[1])
    last_time = time.time()
    last_output_time = time.time()

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        fingerprint = compute_fingerprint(line)
        current_time = time.time()

        if current_time - last_output_time >= 1:
            last_output_time = current_time

        if current_time - last_time >= 1 / rate:
            last_time = current_time

        sys.stdout.write(f"{line}\t{fingerprint}\n")
        sys.stdout.flush()

if __name__ == "__main__":
    main()
